import os
import time
import sync
import crypto.sha256
import net.urllib
import net.http
import encoding.hex
import json

const base_url = ''
const output_dir = 'app'
const user_agent = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
const max_concurrent = 50
const connection_timeout = 10 * time.second

struct Stats {
mut:
	pages_crawled      u64
	pages_saved        u64
	errors             u64
	duplicates_skipped u64
	bytes_downloaded   u64
	start_time         i64
	end_time           i64
}

struct Crawler {
	base_url      string
	domain        string
	output_dir    string
	manifest_path string
	metadata_path string
mut:
	stats          Stats
	stats_mutex    sync.Mutex
	visited        map[string]bool
	visited_mutex  sync.Mutex
	file_mutex     sync.Mutex
	active_workers sync.WaitGroup
	work_queue     chan string
	processing     sync.WaitGroup
}

fn new_crawler() &Crawler {
	parsed := urllib.parse(base_url) or { panic(err) }
	host := parsed.host
	wd := os.getwd()
	out := os.join_path(wd, output_dir)
	if !os.is_dir(out) {
		os.mkdir_all(out) or { panic(err) }
	}
	return &Crawler{
		base_url: base_url
		domain: host
		output_dir: out
		manifest_path: os.join_path(out, 'manifest.txt')
		metadata_path: os.join_path(out, 'metadata.json')
		visited: map[string]bool{}
		work_queue: chan string{cap: 10000}
	}
}

fn (mut c Crawler) is_visited(url string) bool {
	c.visited_mutex.lock()
	defer {
		c.visited_mutex.unlock()
	}
	if url in c.visited {
		return true
	}
	c.visited[url] = true
	return false
}

fn sanitize_filename(url string) string {
	hash := sha256.sum(url.bytes())
	return hex.encode(hash[..]) + '.txt'
}

fn (mut c Crawler) save_content(url string, content string) {
	filename := sanitize_filename(url)
	path := os.join_path(c.output_dir, filename)
	os.write_file(path, content) or {
		c.stats_mutex.lock()
		c.stats.errors++
		c.stats_mutex.unlock()
		return
	}
	content_hash_bytes := sha256.sum(content.bytes())
	content_hash := hex.encode(content_hash_bytes[..])
	line := '${filename}\t${url}\t${content_hash}\n'
	c.file_mutex.lock()
	mut f := os.open_append(c.manifest_path) or {
		c.file_mutex.unlock()
		return
	}
	f.write_string(line) or {}
	f.close()
	c.file_mutex.unlock()
	c.stats_mutex.lock()
	c.stats.pages_saved++
	c.stats_mutex.unlock()
}

fn extract_links(html string, base_url string, domain string) []string {
	mut links := []string{}
	mut idx := 0
	for {
		start_href := html.index_after('href="', idx)
		if start_href == -1 {
			break
		}
		start_quote := start_href + 6
		end_quote := html.index_after('"', start_quote)
		if end_quote == -1 {
			break
		}
		raw_url := html[start_quote..end_quote]
		idx = end_quote
		if raw_url.len < 1 || raw_url.starts_with('#') || raw_url.starts_with('mailto:') || raw_url.starts_with('javascript:') {
			continue
		}
		mut absolute_url := raw_url
		if !raw_url.starts_with('http') {
			parsed_base := urllib.parse(base_url) or { continue }
			if raw_url.starts_with('/') {
				absolute_url = '${parsed_base.scheme}://${parsed_base.host}${raw_url}'
			} else {
				mut path := parsed_base.path
				if !path.ends_with('/') {
					last_slash := path.index_last('/') or { -1 }
					if last_slash != -1 {
						path = path[..last_slash + 1]
					} else {
						path = '/'
					}
				}
				absolute_url = '${parsed_base.scheme}://${parsed_base.host}${path}${raw_url}'
			}
		}
		parsed_link := urllib.parse(absolute_url) or { continue }
		if parsed_link.host != domain {
			continue
		}
		link_clean := absolute_url.split('#')[0]
		links << link_clean
	}
	return links
}

fn clean_html(html string) string {
	mut res := html
	res = res.replace_each([
		'<script', '\x00<script',
		'</script>', '</script>\x00',
		'<style', '\x00<style',
		'</style>', '</style>\x00',
		'<nav', '\x00<nav',
		'</nav>', '</nav>\x00',
		'<footer', '\x00<footer',
		'</footer>', '</footer>\x00',
		'<header', '\x00<header',
		'</header>', '</header>\x00',
		'<noscript', '\x00<noscript',
		'</noscript>', '</noscript>\x00',
		'<aside', '\x00<aside',
		'</aside>', '</aside>\x00',
	])
	parts := res.split('\x00')
	mut sb := []string{}
	for part in parts {
		lower_part := part.to_lower()
		if lower_part.starts_with('<script') || lower_part.starts_with('</script') ||
			lower_part.starts_with('<style') || lower_part.starts_with('</style') ||
			lower_part.starts_with('<nav') || lower_part.starts_with('</nav') ||
			lower_part.starts_with('<footer') || lower_part.starts_with('</footer') ||
			lower_part.starts_with('<header') || lower_part.starts_with('</header') ||
			lower_part.starts_with('<noscript') || lower_part.starts_with('</noscript') ||
			lower_part.starts_with('<aside') || lower_part.starts_with('</aside') {
			continue
		}
		sb << part
	}
	text := sb.join('\n')
	mut in_tag := false
	mut clean := []u8{}
	mut prev_was_space := true
	for ch in text {
		if ch == `<` {
			in_tag = true
			if !prev_was_space {
				clean << ` `
			}
			continue
		}
		if ch == `>` {
			in_tag = false
			prev_was_space = true
			continue
		}
		if !in_tag {
			if ch == `\n` || ch == `\t` || ch == `\r` {
				if !prev_was_space {
					clean << ` `
					prev_was_space = true
				}
			} else if ch == ` ` {
				if !prev_was_space {
					clean << ` `
					prev_was_space = true
				}
			} else {
				clean << ch
				prev_was_space = false
			}
		}
	}
	mut final_str := clean.bytestr().trim_space()
	final_str = final_str.replace_each([
		'&nbsp;', ' ',
		'&lt;', '<',
		'&gt;', '>',
		'&amp;', '&',
		'&quot;', '"',
		'&#39;', "'",
		'&mdash;', '-',
		'&ndash;', '-',
		'&ldquo;', '"',
		'&rdquo;', '"',
	])
	mut lines := []string{}
	for line in final_str.split('\n') {
		trimmed := line.trim_space()
		if trimmed.len > 0 {
			mut normalized := ''
			mut prev_space := false
			for ch in trimmed {
				if ch == ` ` {
					if !prev_space {
						normalized += ' '
						prev_space = true
					}
				} else {
					normalized += ch.ascii_str()
					prev_space = false
				}
			}
			lines << normalized
		}
	}
	return lines.join('\n')
}

fn (mut c Crawler) fetch(url string) ?string {
	mut req := http.new_request(http.Method.get, url, '') or {
		c.stats_mutex.lock()
		c.stats.errors++
		c.stats_mutex.unlock()
		return none
	}
	req.header.add(.user_agent, user_agent)
	resp := req.do() or {
		c.stats_mutex.lock()
		c.stats.errors++
		c.stats_mutex.unlock()
		return none
	}
	if resp.status_code != 200 {
		c.stats_mutex.lock()
		c.stats.errors++
		c.stats_mutex.unlock()
		return none
	}
	ct := resp.header.get(.content_type) or { '' }
	if !ct.contains('text/html') {
		return none
	}
	c.stats_mutex.lock()
	c.stats.bytes_downloaded += u64(resp.body.len)
	c.stats_mutex.unlock()
	return resp.body
}

fn (mut c Crawler) worker() {
	defer c.active_workers.done()
	for {
		select {
			url := <-c.work_queue {
				if c.is_visited(url) {
					c.stats_mutex.lock()
					c.stats.duplicates_skipped++
					c.stats_mutex.unlock()
					c.processing.done()
					continue
				}
				println('[Worker] Processing: ${url}')
				html := c.fetch(url) or {
					c.processing.done()
					continue
				}
				c.stats_mutex.lock()
				c.stats.pages_crawled++
				c.stats_mutex.unlock()
				text := clean_html(html)
				if text.len > 0 {
					c.save_content(url, text)
				}
				links := extract_links(html, url, c.domain)
				for link in links {
					c.processing.add(1)
					c.work_queue <- link
				}
				c.processing.done()
			}
			> 1 * time.second {
				return
			}
		}
	}
}

fn (mut c Crawler) run() {
	c.stats.start_time = time.now().unix_time()
	println('Starting crawl of ${c.base_url} with ${max_concurrent} workers...')
	if os.exists(c.manifest_path) {
		os.rm(c.manifest_path) or {}
	}
	c.processing.add(1)
	c.work_queue <- c.base_url
	for _ in 0 .. max_concurrent {
		c.active_workers.add(1)
		spawn c.worker()
	}
	c.processing.wait()
	c.stats.end_time = time.now().unix_time()
	c.save_metadata()
	duration := c.stats.end_time - c.stats.start_time
	println('=================================================')
	println('Crawl Complete.')
	println('Duration: ${duration}s')
	println('Pages Crawled: ${c.stats.pages_crawled}')
	println('Pages Saved: ${c.stats.pages_saved}')
	println('Errors: ${c.stats.errors}')
	println('Data: ${c.stats.bytes_downloaded / 1024} KB')
}

struct Metadata {
	domain   string
	base_url string
	stats    Stats
}

fn (mut c Crawler) save_metadata() {
	meta := Metadata{
		domain: c.domain
		base_url: c.base_url
		stats: c.stats
	}
	encoded := json.encode(meta)
	os.write_file(c.metadata_path, encoded) or {}
}

fn main() {
	mut crawler := new_crawler()
	crawler.run()
}
